# apply-todays-updates.ps1 -- ONE-SHOT: writes every pending fix from
# today (DB Tools export/import/diff feature, the relay poll timeout
# fix, and the Sync Log backup-logging fix), then rebuilds the exe +
# msi automatically. Backs up every file it overwrites first.
#
# Run from the project ROOT (same folder as main.py, app\, make-msi.bat)
# -- or just run apply-todays-updates.bat, which cds here for you.

$ErrorActionPreference = "Stop"
Set-Location -Path $PSScriptRoot

if (-not (Test-Path "main.py")) {
    Write-Host "ERROR: main.py not found in this folder." -ForegroundColor Red
    Write-Host "Run this from the project root."
    Read-Host "Press Enter to close"
    exit 1
}

$files = @{}
$dbTools = ''
$files['db_tools.py'] = $dbTools

$routesDbTools = ''
$files['app/routes_db_tools.py'] = $routesDbTools

$appInit = ''
$files['app/__init__.py'] = $appInit

$relayClient = ''
$files['relay_client.py'] = $relayClient

$backupLoop = ''
$files['backup_loop.py'] = $backupLoop


foreach ($relPath in $files.Keys) {
    $destPath = Join-Path $PSScriptRoot $relPath
    $destDir = Split-Path $destPath -Parent
    if (-not (Test-Path $destDir)) {
        New-Item -ItemType Directory -Path $destDir -Force | Out-Null
    }
    if (Test-Path $destPath) {
        Write-Host "Backing up $relPath ..."
        Copy-Item $destPath "$destPath.bak" -Force
    }
    Write-Host "Writing $relPath ..."
    try {
        $bytes = [Convert]::FromBase64String($files[$relPath])
        [IO.File]::WriteAllBytes($destPath, $bytes)
    } catch {
        Write-Host "ERROR: failed to write $relPath -- $_" -ForegroundColor Red
        Read-Host "Press Enter to close"
        exit 1
    }
    if (-not (Test-Path $destPath)) {
        Write-Host "ERROR: $relPath was not created." -ForegroundColor Red
        Read-Host "Press Enter to close"
        exit 1
    }
}
Write-Host "All files written and confirmed."

Write-Host ""
Write-Host "============================================================"
Write-Host "  Source updated. Rebuilding exe + msi..."
Write-Host "============================================================"
if (Test-Path "make-msi.bat") {
    cmd /c "make-msi.bat"
} else {
    Write-Host "WARNING: make-msi.bat not found in this folder -- rebuild manually." -ForegroundColor Yellow
}

Write-Host ""
Write-Host "============================================================"
Write-Host "  Done. Files updated:"
Write-Host "    db_tools.py              (new -- export/import/diff)"
Write-Host "    app\routes_db_tools.py   (new -- DB Tools API + admin page)"
Write-Host "    app\__init__.py          (DB Tools registered + busy_timeout fix)"
Write-Host "    relay_client.py          (poll timeout 30s -> 35s)"
Write-Host "    backup_loop.py           (Sync Log now records backup attempts)"
Write-Host "============================================================"
Read-Host "Press Enter to close"
